@Composable
fun VoicePosTheme(content: @Composable () -> Unit) {
    MaterialTheme(colorScheme = darkColorScheme(primary = androidx.compose.ui.graphics.Color(0xFF9B8CFF), secondary = androidx.compose.ui.graphics.Color(0xFF42D6A4)), content = content)
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PosApp(store: Store, printer: PrinterManager, heard: String, voiceStatus: String, scanStatus: String, clearHeard: () -> Unit, listen: () -> Unit, openSpeechSettings: () -> Unit, exportMenu: () -> Unit, importMenu: () -> Unit, pickLogo: () -> Unit, scanDocument: () -> Unit, exportBackup: () -> Unit, importBackup: () -> Unit) {
    var tab by remember { mutableIntStateOf(0) }; var cart by remember { mutableStateOf(emptyList<SaleItem>()) }; var cash by remember { mutableStateOf(store.cash()) }; var tick by remember { mutableIntStateOf(0) }; var filter by remember { mutableIntStateOf(0) }; var editing by remember { mutableStateOf<PendingSale?>(null) }; var settings by remember { mutableStateOf(false) }; var expense by remember { mutableStateOf(false) }; var opening by remember { mutableStateOf(!store.hasOpeningCash()) }; var selectedSale by remember { mutableStateOf<Sale?>(null) }; var manualCart by remember { mutableStateOf(false) }; var customerDialog by remember { mutableStateOf(false) }; var customerName by remember { mutableStateOf("") }; var customerPhone by remember { mutableStateOf("") }
    val menu = remember(tick) { store.menu() }; val profile = remember(tick) { store.profile() }; val sales = remember(tick) { store.sales() }; val expenses = remember(tick) { store.expenses() }; val pending = remember(tick) { store.pending() }
    LaunchedEffect(heard) {
        if (heard.isNotBlank()) { VoiceCommandEngine.parse(heard, menu).forEach { command -> when (command) {
            is VoiceCommand.Add -> { val i=cart.indexOfFirst { it.name.equals(command.item.name,true)&&it.price==command.item.price }; cart=if(i>=0)cart.toMutableList().also{l->l[i]=l[i].copy(qty=l[i].qty+command.item.qty)}else cart+command.item }
            VoiceCommand.Clear -> cart=emptyList(); VoiceCommand.Sales -> tab=3; VoiceCommand.Expenses -> tab=4; VoiceCommand.Reports -> tab=5; VoiceCommand.Settings -> settings=true; VoiceCommand.Menu -> tab=1; VoiceCommand.Kitchen -> tab=2; VoiceCommand.Analytics -> tab=5; VoiceCommand.NewOrder -> cart=emptyList()
            is VoiceCommand.PayLast -> pending.lastOrNull()?.let { pay(it) }
            is VoiceCommand.Quantity -> cart=cart.map{if(it.name.contains(command.name,true))it.copy(qty=(it.qty+command.delta).coerceAtLeast(0))else it}.filter{it.qty>0}
            is VoiceCommand.Remove -> cart=cart.filterNot{it.name.contains(command.name,true)}
            VoiceCommand.CompletePrint -> if(cart.isNotEmpty()){val order=PendingSale(System.currentTimeMillis(),cart,System.currentTimeMillis(),customerName.trim(),customerPhone.trim());store.addPending(order);printer.printKitchen(kitchenReceipt(order,profile,store.theme()));cart=emptyList();customerName="";customerPhone="";tick++}
            VoiceCommand.Complete -> Unit
        } }; clearHeard() }
    }
    fun sendOrder(){if(cart.isNotEmpty())customerDialog=true}; fun sendOrderWithCustomer(name:String,phone:String){customerName=name.trim();customerPhone=phone.trim();val order=PendingSale(System.currentTimeMillis(),cart,System.currentTimeMillis(),customerName,customerPhone);store.addPending(order);printer.printKitchen(kitchenReceipt(order,profile,store.theme()));cart=emptyList();customerName="";customerPhone="";tick++}; fun pay(order:PendingSale){val sale=Sale(order.id,order.items,order.total,System.currentTimeMillis());store.addSale(sale);cash+=sale.total;store.setCash(cash);store.removePending(order.id);printer.printCustomer(customerReceipt(sale,profile,store.theme()));tick++}
    Scaffold(topBar={CenterAlignedTopAppBar(title={Column(horizontalAlignment=Alignment.CenterHorizontally){Text(profile.name.ifBlank{"VOICE POS"},fontWeight=FontWeight.Bold);Text("VOICE POS • PREMIUM",style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.secondary)}},actions={IconButton(onClick={settings=true}){Icon(Icons.Default.Settings,"Settings")}})},bottomBar={NavigationBar{listOf("Sale","Menu","Kitchen","Sales","Expenses","Analytics").forEachIndexed{i,n->NavigationBarItem(tab==i,{tab=i},icon={Icon(listOf(Icons.Default.PointOfSale,Icons.Default.MenuBook,Icons.Default.Restaurant,Icons.Default.ReceiptLong,Icons.Default.Payments,Icons.Default.Insights)[i],n)},label={Text(n)})}}},floatingActionButton={ExtendedFloatingActionButton(onClick=listen,icon={Icon(Icons.Default.Mic,"Power Voice")},text={Text("POWER VOICE")},shape=CircleShape)}){padding->Box(Modifier.fillMaxSize().padding(padding)){when(tab){0->QuickSale(cart,voiceStatus,::sendOrder,listen,openSpeechSettings,{cart=emptyList()},{manualCart=true}){item,delta->cart=cart.map{if(it==item)it.copy(qty=(it.qty+delta).coerceAtLeast(0))else it}.filter{it.qty>0}};1->MenuPage(menu,store,tick,{tick++},exportMenu,importMenu,scanDocument){item->val i=cart.indexOfFirst{it.name.equals(item.name,true)&&it.price==item.price};cart=if(i>=0)cart.toMutableList().also{l->l[i]=l[i].copy(qty=l[i].qty+1)}else cart+SaleItem(item.name,1,item.price);tab=0};2->KitchenQueue(pending,profile,printer,::pay){editing=it};3->SalesPage(sales.filter{inRange(it.time,filter)},filter,{filter=it},{selectedSale=it});4->ExpensesPage(expenses.filter{inRange(it.time,filter)},filter,{filter=it}){expense=true};5->Analytics(sales.filter{inRange(it.time,filter)},expenses.filter{inRange(it.time,filter)},cash,filter,{filter=it})}}}
    if(settings)SettingsPage(store,printer,pickLogo,exportBackup,importBackup){settings=false;tick++}; if(opening)OpeningCash{store.setOpeningCash(it);cash=it;opening=false}; if(expense)ExpenseDialog({a,b,c->store.addExpense(Expense(System.currentTimeMillis(),a,b,c,System.currentTimeMillis()));expense=false;tick++}){expense=false}; selectedSale?.let{SaleDetailDialog(it,profile,printer,store.theme()){selectedSale=null}}; if(customerDialog)CustomerDetailsDialog({n,p->customerDialog=false;sendOrderWithCustomer(n,p)}){customerDialog=false}; editing?.let{EditDialog(it,{u->store.replacePending(u);editing=null;tick++}){editing=null}}; if(manualCart)ManualCartDialog(menu,{item->val i=cart.indexOfFirst{it.name.equals(item.name,true)&&it.price==item.price};cart=if(i>=0)cart.toMutableList().also{l->l[i]=l[i].copy(qty=l[i].qty+1)}else cart+SaleItem(item.name,1,item.price)},{n,q,p->cart+=SaleItem(n,q,p)}){manualCart=false}
}

@Composable private fun QuickSale(cart:List<SaleItem>,voiceStatus:String,send:()->Unit,listen:()->Unit,openSpeechSettings:()->Unit,clear:()->Unit,manual:()->Unit,changeQty:(SaleItem,Int)->Unit){Column(Modifier.fillMaxSize().padding(16.dp).verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(12.dp)){Card(Modifier.fillMaxWidth()){Column(Modifier.padding(18.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Mic,null);Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text("Power Voice checkout",fontWeight=FontWeight.Bold);Text("On-device first • multi-item orders",style=MaterialTheme.typography.bodySmall)};IconButton(onClick=listen){Icon(Icons.Default.MicNone,"Listen")}};AssistChip(onClick=listen,label={Text(voiceStatus)},leadingIcon={Icon(Icons.Default.WifiOff,null)});Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick=manual,modifier=Modifier.weight(1f)){Icon(Icons.Default.Keyboard,null);Text("MANUAL ADD")};OutlinedButton(onClick=listen,modifier=Modifier.weight(1f)){Icon(Icons.Default.Mic,null);Text("TRY VOICE")}};if(voiceStatus.contains("unavailable",true))OutlinedButton(onClick=openSpeechSettings,modifier=Modifier.fillMaxWidth()){Text("Check Speech Settings")};Text("Try: 2 shawarma 300 each and 1 fries 150",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}};Card(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp)){Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween,Alignment.CenterVertically){Text("Current order",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);if(cart.isNotEmpty())TextButton(onClick=clear){Text("Clear")}};if(cart.isEmpty())EmptyState(Icons.Default.ShoppingCart,"No items yet","Use Power Voice or Manual Add.")else{cart.forEach{item->Row(Modifier.fillMaxWidth().padding(vertical=7.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(item.name,fontWeight=FontWeight.SemiBold);Text(item.qty.toString()+" × "+money(item.price),style=MaterialTheme.typography.bodySmall)};IconButton(onClick={changeQty(item,-1)}){Icon(Icons.Default.RemoveCircleOutline,null)};Text(money(item.total),fontWeight=FontWeight.Bold);IconButton(onClick={changeQty(item,1)}){Icon(Icons.Default.AddCircleOutline,null)}}};HorizontalDivider();Row(Modifier.fillMaxWidth().padding(top=12.dp),Arrangement.SpaceBetween){Text("TOTAL",fontWeight=FontWeight.Bold);Text(money(cart.sumOf{it.total}),fontWeight=FontWeight.Bold)};Button(onClick=send,modifier=Modifier.fillMaxWidth().padding(top=12.dp)){Text("PRINT KITCHEN & HOLD PAYMENT")}}}}}

@Composable private fun ManualCartDialog(menu:List<MenuItem>,add:(MenuItem)->Unit,addCustom:(String,Int,Double)->Unit,close:()->Unit){var query by remember{mutableStateOf("")};var n by remember{mutableStateOf("")};var p by remember{mutableStateOf("")};var q by remember{mutableStateOf("1")};val filtered=menu.filter{it.name.contains(query,true)||it.variant.contains(query,true)||it.size.contains(query,true)};AlertDialog(onDismissRequest=close,title={Text("Manual Add Products")},text={Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(query,{query=it},label={Text("Search menu")},singleLine=true);filtered.forEach{item->Card(Modifier.fillMaxWidth().clickable{add(item)}){Row(Modifier.padding(12.dp)){Column(Modifier.weight(1f)){Text(item.name,fontWeight=FontWeight.SemiBold);Text(money(item.price),style=MaterialTheme.typography.bodySmall)};Icon(Icons.Default.AddCircleOutline,null)}}};HorizontalDivider();OutlinedTextField(n,{n=it},label={Text("Custom product")});Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(q,{q=it.filter(Char::isDigit)},label={Text("Qty")},modifier=Modifier.weight(1f));OutlinedTextField(p,{p=it},label={Text("Price")},modifier=Modifier.weight(1f))};Button(onClick={val qty=q.toIntOrNull()?:0;val price=p.toDoubleOrNull()?:0.0;if(n.isNotBlank()&&qty>0&&price>0){addCustom(n,qty,price);n="";p="";q="1"}},modifier=Modifier.fillMaxWidth()){Text("ADD CUSTOM PRODUCT")}}},confirmButton={TextButton(onClick=close){Text("DONE")}})}

@Composable private fun MenuPage(menu:List<MenuItem>,store:Store,tick:Int,refresh:()->Unit,exportMenu:()->Unit,importMenu:()->Unit,scanDocument:()->Unit,addToCart:(MenuItem)->Unit){var adding by remember{mutableStateOf(false)};Column(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(6.dp)){Button(onClick={adding=true},modifier=Modifier.weight(1f)){Icon(Icons.Default.Add,null);Text("Add")};OutlinedButton(onClick=scanDocument,modifier=Modifier.weight(1f)){Icon(Icons.Default.DocumentScanner,null);Text("AI Scan")}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(6.dp)){OutlinedButton(onClick=exportMenu,modifier=Modifier.weight(1f)){Text("CSV Export")};OutlinedButton(onClick=importMenu,modifier=Modifier.weight(1f)){Text("CSV Import")}};Text("AI Scan reads product names and prices from photos/PDF menus and adds detected products automatically.",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant);if(menu.isEmpty())EmptyState(Icons.Default.MenuBook,"No products","Add products or scan a menu image/PDF.");LazyColumn{items(menu){item->Card(Modifier.fillMaxWidth().clickable{addToCart(item)}){Row(Modifier.fillMaxWidth().padding(14.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(item.name,fontWeight=FontWeight.SemiBold);Text(money(item.price),style=MaterialTheme.typography.bodySmall)};IconButton(onClick={store.removeMenuItem(item.id);refresh()}){Icon(Icons.Default.Delete,"Delete")}}}}}};if(adding)AddMenuDialog({n,v,s,p->store.addMenuItem(MenuItem(System.currentTimeMillis(),n.trim(),p,v.trim(),s.trim()));adding=false;refresh()}){adding=false}}

@Composable private fun SettingsPage(store:Store,printer:PrinterManager,pickLogo:()->Unit,exportBackup:()->Unit,importBackup:()->Unit,close:()->Unit){var profile by remember{mutableStateOf(store.profile())};var theme by remember{mutableStateOf(store.theme())};var customer by remember{mutableStateOf(store.customerPrinterAddress())};var kitchen by remember{mutableStateOf(store.kitchenPrinterAddress())};AlertDialog(onDismissRequest=close,title={Text("Business & Print Settings")},text={Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(7.dp)){Text("Business Data Transfer",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);Text("Export the full business backup and import it on the new phone.",style=MaterialTheme.typography.bodySmall);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick=exportBackup,modifier=Modifier.weight(1f)){Text("EXPORT BACKUP")};OutlinedButton(onClick=importBackup,modifier=Modifier.weight(1f)){Text("IMPORT BACKUP")}};Text("Company",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);OutlinedTextField(profile.name,{profile=profile.copy(name=it)},label={Text("Company Name")});OutlinedTextField(profile.address,{profile=profile.copy(address=it)},label={Text("Address")},minLines=3);OutlinedTextField(profile.phone,{profile=profile.copy(phone=it)},label={Text("Phone")});OutlinedTextField(profile.footer,{profile=profile.copy(footer=it)},label={Text("Footer message")});Text("Company Logo",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Text(if(profile.logoPath.isBlank())"No logo uploaded"else"Logo uploaded ✓",Modifier.weight(1f));OutlinedButton(onClick=pickLogo){Text("UPLOAD / CHANGE")}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Sale receipt logo");Switch(profile.saleLogoEnabled,{profile=profile.copy(saleLogoEnabled=it)})};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Kitchen receipt logo");Switch(profile.kitchenLogoEnabled,{profile=profile.copy(kitchenLogoEnabled=it)})};Text("Receipt style",fontWeight=FontWeight.Bold);Row(Modifier.horizontalScroll(rememberScrollState())){ReceiptTheme.values().forEach{t->FilterChip(theme==t,{theme=t},label={Text(t.name)})}};Text("Bluetooth printers",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);printer.devices.forEach{device->Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Text(device.name?:device.address,Modifier.weight(1f),maxLines=1);TextButton(onClick={customer=device.address}){Text(if(customer==device.address)"Receipt ✓"else"Receipt")};TextButton(onClick={kitchen=device.address}){Text(if(kitchen==device.address)"Kitchen ✓"else"Kitchen")}}}},confirmButton={TextButton(onClick={store.saveProfile(profile);store.setTheme(theme);store.setCustomerPrinterAddress(customer);store.setKitchenPrinterAddress(kitchen);close()}){Text("SAVE")}},dismissButton={TextButton(onClick=close){Text("CLOSE")}})}
